                'type' => 'คุณภาพ',
                'code' => 'NCP-4',
                'description' => ' ระบบสารสนเทศเพื่อการบริหารและการตัดสินใจ หมายถึง ระบบการจัดเก็บ ประมวลผล วิเคราะห์ข้อมูล และนำ สารสนเทศไปใช้เพื่อการตัดสินใจ ครอบคลุมทุกพันธกิจที่สถาบันกำหนด โดยแสดงผลข้อมูลที่เป็นปัจจุบัน ถูกต้อง พร้อมใช้ และเข้าถึงได้ ทำให้ผู้บริหารนำไปใช้ในการบริหารงานและตัดสินใจ ครอบคลุมทุกพันธกิจที่สถาบันกำหนด ดังนี้ 
                     1) ด้านการบริหาร หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหารสามารถนำมาพิจารณาในการ ตัดสินใจได้ ประกอบด้วย 
                                1.1) ด้านการเงิน การงบประมาณ แสดงถึงการนำข้อมูลมาวิเคราะห์ด้วยค่าสถิติเชิงพรรณนา เช่น ร้อยละ ค่าเฉลี่ย ของเงินงบประมาณที่ได้รับและรายจ่ายในแต่ละปีงบประมาณแต่ละไตรมาส เพื่อพิจารณาบริหาร จัดการให้ทันเวลา การเสนอรายงานสารสนเทศอาจเป็นการบรรยาย ตาราง แผนภูมิ แผนภาพที่สื่อต่อความเข้าใจได้ ง่าย เป็นต้น 
                                1.2) ด้านการบริหารงานบุคคล แสดงถึงจำนวนร้อยละของบุคลากรที่หน่วยงานมีอยู่ จำแนกตามวุฒิ การศึกษา อายุ เพศ ระดับตำแหน่ง ตำแหน่งทางวิชาการ การลาศึกษาต่อ การลาฝึกอบรม ภาระงานของอาจารย์ และบุคลากร ประวัติของบุคลากรที่จำเป็นต่อการบริหารงานและการตัดสินใจของผู้บริหาร เป็นต้น 
                                1.3) ด้านครุภัณฑ์แสดงถึงจำนวนครุภัณฑ์ที่จำเป็นในการจัดการเรียนการสอน ที่หน่วยงานมีอยู่ เช่น การเปรียบเทียบการเพิ่มขึ้น - ลดลงในแต่ละปี รายละเอียดที่สามารถทราบถึงวันเวลา การซื้อ การซ่อม การจำหน่าย การยืม การคืน เพื่อการตัดสินใจในการจัดหาครุภัณฑ์ที่จำเป็น เป็นต้น 
                     2) ด้านการเรียนการสอน หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศผู้บริหารนำมาใช้ในการตัดสินใจ ด้านการเรียนการสอนของหน่วยงาน เช่น การแสดงตารางสอน ในแต่ละชั้นปีการเปรียบเทียบจำนวนนิสิต/นักศึกษาแรกเข้าในแต่ละปี การเปรียบเทียบจำนวนผู้สำเร็จการศึกษาและนิสิต/นักศึกษาแรกเข้าในแต่ละรุ่น แต่ละปี หลักสูตรที่เปิดสอน จำนวนรายวิชาที่สอนในแต่ละปีการศึกษา ภาระงานของอาจารย์ผู้สอนในแต่ละภาคการศึกษา เป็นต้น 
                     3) ด้านการวิจัย หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศผู้บริหารนำมาใช้ในการตัดสินใจด้านการ วิจัยของหน่วยงาน เช่น จำนวน/ร้อยละของงานวิจัย เปรียบเทียบจำนวนงานวิจัยของอาจารย์ในแต่ละปี จำนวนทุน ที่ได้รับการสนับสนุนจากภายใน/ภายนอกหน่วยงานเรื่องที่ทำการวิจัยในแต่ละสาขาวิชา จำนวน/ร้อยละของ งานวิจัยที่ตีพิมพ์ในแต่ละปี บทคัดย่อที่ผู้สนใจสามารถเข้าถึงได้ เป็นต้น 
                      4) ด้านการบริการวิชาการ หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหารนำมาใช้ในการ ตัดสินใจด้านการบริการวิชาการของหน่วยงาน เช่น จำนวน/ร้อยละ การเปรียบเทียบงานบริการวิชาการของอาจารย์ ในแต่ละปี จำนวนงบประมาณที่ได้รับการสนับสนุนจากภายใน/ภายนอกหน่วยงาน จำนวนอาจารย์ที่ให้บริการ วิชาการแก่สังคม หลักสูตร/โครงการ/กิจกรรมที่ให้บริการในแต่ละปี เป็นต้น 
                      5) ด้านการทำนุบำรุงศิลปะและวัฒนธรรม หมายถึง มีการจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหาร สามารถนำมาพิจารณาในการตัดสินใจด้านการทำนุบำรุงศิลปะและวัฒนธรรม เช่น จำนวน/ร้อยละ การเปรียบเทียบ งาน/กิจกรรมทำนุบำรุงศิลปะและวัฒนธรรมในแต่ละปี จำนวนงบประมาณที่ได้รับการสนับสนุนจากภายใน/ ภายนอกหน่วยงาน จำนวนอาจารย์ที่งาน/กิจกรรมทำนุบำรุงศิลปะและวัฒนธรรม หลักสูตร/โครงการ/กิจกรรมที่ ให้บริการในแต่ละปี เป็นต้น ',
