                     แผนบริหารความเสี่ยง หมายถึง แผนการจัดการเพื่อป้องกันความเสี่ยงต่าง ๆ ที่เกี่ยวกับการจัดการศึกษา และการบริหารที่อาจเกิดขึ้น ซึ่งเกิดจากการวิเคราะห์ความเสี่ยงอย่างรอบด้าน สอดคล้องกับกลยุทธ์ของสถาบัน เช่น ความเสี่ยงด้านกลยุทธ์หรือยุทธศาสตร์ของสถาบัน ความเสี่ยงด้านนโยบาย กฎหมาย ระเบียบ ข้อบังคับ และความ เสี่ยงด้านการปฏิบัติงาน ความเสี่ยงด้านบุคลากร การเงิน งบประมาณ ระบบเทคโนโลยีสารสนเทศ อาคารสถานที่ เป็นต้น 
