                'type' => 'คุณภาพ',
                'code' => 'NCS-3',
                'description' => 'อาจารย์ประจํา หมายถึง บุคคลที่ดํารงตําแหน่ง อาจารย์ ผู้ช่วยศาสตราจารย์ รองศาสตราจารย์ และศาสตราจารย์ ทั้งนี้ให้รวมถึงตําแหน่งที่เรียกชื่ออย่างอื่น ในสถาบันอุดมศึกษาที่เปิดสอนหลักสูตรพยาบาลศาสตรบัณฑิต ที่มีหน้าที่รับผิดชอบตามพันธกิจของการอุดมศึกษา และปฏิบัติหน้าที่เต็มเวลา มีคุณวุฒิระดับปริญญาโท สาขาพยาบาลศาสตร์หรือสาขาที่สัมพันธ์กันเป็นอย่างน้อย โดยต้องมีคุณวุฒิปริญญาตรีทางการพยาบาลและการผดุงครรภ์ มีใบอนุญาตเป็นผู้ประกอบวิชาชีพการพยาบาลและการผดุงครรภ์ ชั้นหนึ่ง หรือใบอนุญาตเป็นผู้ประกอบวิชาชีพการพยาบาลชั้นหนึ่ง ที่ไม่หมดอายุ สําหรับอาจารย์ที่สอนด้านการพยาบาลมารดา-ทารกและการผดุงครรภ์จะต้องมีใบอนุญาตเป็นผู้ประกอบวิชาชีพการพยาบาลและการผดุงครรภ์ ชั้นหนึ่ง และมีประสบการณ์กา
                   ปฏิบัติการพยาบาลมาแล้วไม่น้อยกว่า 2 ปี และมีประสบการณ์การสอนทางการพยาบาลในสถาบันการศึกษาพยาบาลมาแล้วไม่น้อยกว่า 1 ปี ทั้งนี้ถ้าสําเร็จการศึกษาสาขาอื่นที่ไม่ใช่สาขาพยาบาลศาสตร์และไม่มีตําแหน่งทางวิชาการสาขาการพยาบาล ต้องมีจํานวนรวมไม่เกินร้อยละ 15 ของจํานวนอาจารย์ประจําทั้งหมด
                   กรณีอาจารย์ประจําไม่มีประสบการณ์การสอนทางการพยาบาลในสถาบันการศึกษา ให้สถาบันการศึกษาจัดให้มีระบบอาจารย์พี่เลี้ยง ซึ่งเป็นอาจารย์ประจําหลักสูตรที่มีประสบการณ์การจัดการเรียนการสอนในสาขา วิชานั้นเป็นอาจารย์พี่เลี้ยง โดยให้มีระยะเวลาไม่น้อยกว่า 1 ภาคการศึกษา หรือให้มีการจัดอบรม หลักสูตรด้านการจัดการเรียนการสอนทางการพยาบาลอย่างเป็นระบบ
                   สําหรับอาจารย์ประจําที่สถาบันอุดมศึกษารับเข้าใหม่ ต้องมีคะแนนทดสอบความสามารถภาษาอังกฤษได้ตามเกณฑ์ที่กําหนดไว้ในประกาศคณะกรรมการการอุดมศึกษา เรื่อง มาตรฐานความสามารถภาษาอังกฤษของอาจารย์ประจํา หรือมีระบบพัฒนาคะแนนทดสอบความสามารถภาษาอังกฤษให้ได้ตามเกณฑ์ที่กําหนดฯ ภายในระยะเวลา 3 ปี
                    การนับระยะเวลาการปฏิบัติงานของอาจารย์ประจํา ต้องไม่น้อยกว่า 9 เดือนต่อปีการศึกษา คิดเป็น 1 คน ในกรณีปฏิบัติงาน 6 เดือนขึ้นไป แต่ไม่ถึง 9 เดือน คิดเป็น 0.5 คน
