                'description' => ' อาจารย์ประจําหลักสูตร หมายถึง อาจารย์พยาบาลประจําที่มีผลงานทางวิชาการที่ไม่ใช่ส่วนหนึ่งของการศึกษาเพื่อรับปริญญา และเป็นผลงานทางวิชาการที่ได้รับการเผยแพร่ตามหลักเกณฑ์ที่กําหนดในการพิจารณาแต่งตั้งให้บุคคลดํารงตําแหน่งทางวิชาการอย่างน้อย 1 รายการ ในรอบ 5 ปีย้อนหลัง (หากเป็นผลงานวิชาการที่เผยแพร่หลัง 24 มิถุนายน 2565 เป็นต้นไป ต้องเป็นชื่อแรกหรือผู้ประพันธ์บรรณกิจเท่านั้น)
                  การนับระยะเวลาการปฏิบัติงานของอาจารย์ประจําหลักสูตร ต้องไม่น้อยกว่า 9 เดือนต่อปีการศึกษา คิดเป็น 1 คน ในกรณีปฏิบัติงาน 6 เดือนขึ้นไป แต่ไม่ถึง 9 เดือน คิดเป็น 0.5 คน
                 กรณีหลักสูตรร่วมผลิตกับหน่วยงานภายนอกที่ไม่ใช่สถาบันการศึกษาหากจําเป็นมีอาจารย์ประจําหลักสูตรที่มาจากหน่วยงานภายนอกนั้นได้ต้องสําเร็จการศึกษาระดับปริญญาโทตรงกับสาขาวิชาที่รับผิดชอบและมีประสบการณ์ในการปฏิบัติการให้การพยาบาลในสาขาวิชาที่รับผิดชอบอย่างต่อเนื่องไม่น้อยกว่า 6 ปี และต้องมีภาระงานในการจัดการเรียนการสอนไม่น้อยกว่า 12 ชั่วโมงต่อสัปดาห์ เป็นระยะเวลาต่อเนื่องอย่างน้อย 1 ภาคการศึกษา คิดเป็น 0.5 คน โดยมีจํานวนไม่มากกว่าร้อยละ 20 ของอาจารย์ประจําหลักสูตรทั้งหมด',
