                ระบบสารสนเทศบริหารงานบุคคล ที่แสดงถึงร้อยละของบุคลากรที่หน่วยงานมีอยู่ จำแนกตามวุฒิการศึกษา อายุ เพศ ระดับตำแหน่ง ตำแหน่งทางวิชาการ การลาศึกษาต่อ การลาฝึกอบรม ภาระงานของอาจารย์และบุคลากร
                ระบบสารสนเทศด้านครุภัณฑ์ ที่แสดงถึงจำนวนครุภัณฑ์ที่จำเป็นในการจัดการเรียนการสอนที่หน่วยงานมีอยู่ เช่น การเปรียบเทียบการเพิ่มขึ้น ลดลงในแต่ละปี รายละเอียดที่สามารถทราบถึงวันเวลา การซื้อ การซ่อม การจำหน่าย การยืม การคืน เพื่อการตัดสินใจในการจัดหาครุภัณฑ์
          	    2. มีระบบสารสนเทศเพื่อการตัดสินใจด้านการเรียนการสอน หมายถึง การจัดการข้อมูลเพื่อให้เป้นสารสนเทศในการตัดสินใจด้านการเรียนการสอนของหน่วยงาน เช่น การแสดงตารางสอน ในแต่ละชั้นปี การเปรียบเทียบจำนวนนิสิต/นักศึกษาแรกเข้าในแต่ละปี การเปรียบเทียบจำนวนผู้สำเร็จการศึกษาและนิสิต/นักศึกษาแรกเข้าในแต่ละรุ่น แต่ละปี หลักสูตรที่เปิดสอน จำนวนรายวิชาที่สอนในแต่ละปีการศึกษา ภาระงานของอาจารย์ผู้สอนในแต่ละภาคการศึกษา เป็นต้น
      		    3. มีระบบสารสนเทศเพื่อการตัดสินใจด้านการวิจัย หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหารสามารถนำมาพิจารณาในการตัดสินใจด้านการวิจัยของหน่วยงาน เช่น จำนวน/ร้อยละของงานวิจัยเปรียบเทียบงงานบริการวิชาการของอาจารย์ในแต่ละปี  จำนวนทุนที่ได้รับการสนับสนุนจากภายใน/ภายนอกหน่วยงาน เรื่องที่ทำการวิจัยในแต่ละสาขาวิชา จำนวน/ร้อยละของงานวิจัยที่ตีพิมพ์ในแต่ละปี บทคัดย่อที่ผู้สนใจสามารถเข้าถึงได้
      		    4. มีระบบสารสนเทศเพื่อการตัดสินใจด้านการบริการวิชาการ หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหารสามารถนำมาพิจารณาในการตัดสินใจด้านการบริการวิชาการของหน่วยงาน เช่น จำนวน/ร้อยละ การเปรียบเทียบงานบริการวิชาการของอาจารย์ในแต่ละปี จำนวนงบประมาณที่ได้รับการสนับสนุนจากภายใน/ภายนอกหน่วยงาน จำนวนอาจารย์ที่ให้บริการวิชาการแก่สังคม หลักสูตร/โครงการ/กิจกรรมที่ให้บริการในแต่ละปี
                 5. มีระบบสารสนเทศเพื่อการตัดสินใจ ด้านการทำนุบำรุงศิลปะและวัฒนธรรม หมายถึง การจัดการข้อมูลเพื่อให้เป็นสารสนเทศที่ผู้บริหารสามารถนำมาพิจารณาในการตัดสินใจด้านการทำนุบำรุงศิลปะและวัฒนธรรมของหน่วยงาน เช่น จำนวนโครงการ/กิจกรรมด้านศิลปวัฒนธรรมของอาจารย์และนิสิต/นักศึกษาในแต่ละปี จำนวนงบประมาณที่ได้รับการสนับสนุนจากภายใน/ภายนอกหน่วยงาน จำนวนอาจารย์ที่เข้าร่วมในโครงการทำนุบำรุงศิลปะและวัฒนธรรม',
