                      แผนปฏิบัติงานประจำปี หมายถึง แผนระยะสั้นที่มีระยะเวลาดำเนินการภายใน 1 ปี เป็นแผนที่ถ่ายทอด แผนกลยุทธ์/ยุทธศาสตร์ ลงสู่การปฏิบัติ เพื่อให้เกิดการดำเนินงานจริง ประกอบด้วย โครงการหรือกิจกรรมต่าง ๆ ที่ จะต้องดำเนินการในปีนั้น ๆ เพื่อให้บรรลุเป้าหมายตัวบ่งชี้ความสำเร็จของแผนกลยุทธ์/ ยุทธศาสตร์ และกำหนดค่า เป้าหมายของโครงการที่สอดคล้องกับตัวบ่งชี้ รวมทั้งระบุผู้รับผิดชอบโครงการ/กิจกรรม งบประมาณ ทรัพยากรที่ ต้องใช้ในการดำเนินการ และเมื่อดำเนินงานแล้ว มีผลการดำเนินงานตามแผนปฏิบัติปฏิบัติการ 
                       แผนการจัดสรรงบประมาณ หมายถึง แผนการจัดสรรงบประมาณทุกประเภทเป็นรายปีที่สอดคล้องกับ วิสัยทัศน์ และกลยุทธ์/ ยุทธศาสตร์ มีการวิเคราะห์ การประเมินการใช้งบประมาณตามพันธกิจ เมื่อดำเนินการแล้วมี การประเมินแผนการจัดการสรรงบประมาณ 
                       การถ่ายทอดกลยุทธ์/ ยุทธศาสตร์ หมายถึง กระบวนการนำข้อมูลเกี่ยวกับ กลยุทธ์/ ยุทธศาสตร์ ให้ บุคลากรรับรู้ เช่น การใช้ช่องทางออนไลน์ การประชุมชี้แจงแลกเปลี่ยน การติดประกาศ เป็นต้น เมื่อครบวงรอบการ ดำเนินงานมีการประเมินความพึงพอใจของช่องทางที่ใช้ในการถ่ายทอด/สื่อสาร กลยุทธ์/ยุทธศาสตร์ และการ ประเมินผลการรับรู้ของบุคลากรต่อกลยุทธ์/ยุทธศาสตร์ ที่ได้รับการถ่ายทอด ',
