            [
                // id-18
                'name' => 'ตัวบ่งชี้ที่ 3 การประพฤติตามกฎหมายและจริยธรรม ',
                'categorie_id' => 8,
                'year' => 2026,
                'type' => 'คุณภาพ',
                'code' => 'NCP-3',
                'description' => 'การประพฤติตามกฎหมายและจริยธรรม หมายถึง กระบวนการที่สถาบันดำเนินการตามมาตรฐาน ข้อกำหนด กฏหมาย ระเบียบ ข้อบังคับ และหลักธรรมาภิบาลของการบริหารกิจการบ้านเมืองที่ดีหรือการ ดำเนินการตามหลักคุณธรรมและความโปร่งใสของการดำเนินงาน และการจัดการข้อร้องเรียน อุทธรณ์ ร้องทุกข์ 
                 หลักธรรมาภิบาล หมายถึง การปกครอง การบริหาร การจัดการ การควบคุม ดูแลกิจการต่าง ๆ ให้ เป็นไปในครรลองธรรม โดยยึดตามหลักธรรมาภิบาลของการบริหารกิจการบ้านเมืองที่ดี (Good Governance) 10 ประการ ที่เหมาะสมจะนำมาปรับใช้ในหน่วยงานมี 10 ประการ ดังนี้
                  1. หลักประสิทธิผล (Effectiveness) คือ ผลการปฏิบัติราชการที่บรรลุวัตถุประสงค์และเป้าหมายของ แผนการปฏิบัติราชการตามที่ได้รับงบประมาณมาดำเนินการ รวมถึงสามารถ เทียบเคียงกับส่วนราชการหรือ หน่วยงานที่มีภารกิจคล้ายคลึงกันและมีผลการปฏิบัติงานใน ระดับชั้นนำของประเทศเพื่อให้เกิดประโยชน์สุขต่อ ประชาชนโดยการปฏิบัติราชการ จะต้องมีทิศทางยุทธศาสตร์และเป้าประสงค์ที่ชัดเจนมีกระบวนการปฏิบัติงานและ ระบบงานที่เป็นมาตรฐานรวมถึงมีการติดตามประเมินผลและพัฒนาปรับปรุงอย่างต่อเนื่อง และเป็นระบบ 
                   2. หลักประสิทธิภาพ (Efficiency) คือ การบริหารราชการตามแนวทางการกำกับดูแลที่ดีที่ มีการออกแบบกระบวนการปฏิบัติงานโดยใช้เทคนิคและเครื่องมือการบริหารจัดการที่ เหมาะสมให้องค์การสามารถ ใช้ทรัพยากรทั้งด้านต้นทุน แรงงานและระยะเวลาให้เกิดประโยชน์สูงสุดต่อการพัฒนาขีดความสามารถในการปฏิบัติ ราชการตามภารกิจเพื่อตอบสนองความต้องการของประชาชนและผู้มีส่วนได้ส่วนเสียทุกกลุ่ม 
                   3. หลักการตอบสนอง (Responsiveness) คือ การให้บริการที่สามารถดำเนินการได้ภายในระยะเวลา ที่กำหนด และสร้างความเชื่อมั่น ความไว้วางใจ รวมถึงตอบสนองความคาดหวัง หรือความต้องการของประชาชน ผู้รับบริการ และผู้มีส่วนได้ส่วนเสียที่มีความหลากหลาย และมีความแตกต่าง 
                   4. หลักภาระรับผิดชอบ (Accountability) คือ การแสดงความรับผิดชอบในการปฏิบัติหน้าที่และผลงาน ต่อเป้าหมายที่กำหนดไว้ โดยความรับผิดชอบนั้นควรอยู่ในระดับที่สนองต่อความคาดหวังของสาธารณะ รวมทั้งการ แสดงถึงความสำนึกในการรับผิดชอบต่อปัญหาสาธารณะ 
                   5. หลักความโปร่งใส (Transparency) คือ กระบวนการเปิดเผยอย่างตรงไปตรงมาชี้แจงได้เมื่อมี ข้อสงสัยและสามารถเข้าถึงข้อมูลข่าวสารอันไม่ต้องห้ามตามกฎหมายได้อย่างเสรีโดยประชาชนสามารถรู้ทุกขั้นตอน ในการดำเนินกิจกรรมหรือกระบวนการต่างๆ และ สามารถตรวจสอบได้ 
                   6. หลักการมีส่วนร่วม (Participation) คือ กระบวนการที่ข้าราชการ ประชาชน และผู้มีส่วนได้เสีย ทุกกลุ่มมีโอกาสได้เข้าร่วมในการรับรู้เรียนรู้ ทำความเข้าใจ ร่วมแสดงทัศนะ ร่วมเสนอปัญหาหรือ ประเด็นที่สำคัญ ที่เกี่ยวข้อง ร่วมคิดแนวทาง ร่วมการแก้ไขปัญหา ร่วมในกระบวนการตัดสินใจ และร่วมกระบวนการพัฒนาในฐานะ หุ้นส่วนการพัฒนา 
                   7. หลักการกระจายอำนาจ (Decentralization) คือ การถ่ายโอนอำนาจการตัดสินใจ ทรัพยากร และ ภารกิจจากส่วนราชการส่วนกลางให้แก่หน่วยการปกครองอื่นๆ (ราชการ บริหารส่วนท้องถิ่น) และภาคประชาชน ดำเนินการแทนโดยมีอิสระตามสมควรรวมถึงการ มอบอำนาจและความรับผิดชอบในการตัดสินใจและการดำเนินการให้แก่บุคลากร โดย มุ่งเน้นการสร้างความพึงพอใจในการให้บริการต่อผู้รับบริการและผู้มีส่วนได้เสียการ ปรับปรุงกระบวนการ และเพิ่มผลิตภาพเพื่อผลการดำเนินงานที่ดีของส่วนราชการ 
                  8. หลักนิติธรรม (Rule of Law) คือ การใช้อำนาจของกฎหมาย กฎระเบียบข้อบังคับในการบริหาร ราชการด้วยความเป็นธรรม ไม่เลือกปฏิบัติและคำนึงถึงสิทธิเสรีภาพของผู้มีส่วนได้เสีย 
                  9. หลักความเสมอภาค (Equity) คือ การได้รับการปฏิบัติและได้รับบริการอย่างเท่าเทียมกัน โดยไม่มี การแบ่งแยกด้านชายหรือหญิง ถิ่นกำเนิด เชื้อชาติ ภาษา เพศ อายุ ความพิการ สภาพทางกายหรือสุขภาพ สถานะ ของบุคคล ฐานะทางเศรษฐกิจและสังคม ความเชื่อทางศาสนา การศึกษา การฝึกอบรม และอื่นๆ 
                   10. หลักมุ่งเน้นฉันทามติ (Consensus Oriented) คือ การหาข้อตกลงทั่วไปภายในกลุ่มผู้มีส่วนได้เสีย ที่เกี่ยวข้อง ซึ่งเป็นข้อตกลงที่เกิดจากการใช้กระบวนการเพื่อหาข้อคิดเห็น จากกลุ่มบุคคลที่ได้รับประโยชน์และเสีย ประโยชน์ โดยเฉพาะกลุ่มที่ได้รับผลกระทบโดยตรงซึ่งต้องไม่มีข้อคัดค้านที่ยุติไม่ได้ในประเด็นที่สำคัญ โดยฉันทามติ ไม่จำเป็นต้องหมายความว่าเป็นความเห็นพ้องโดยเอกฉันท์ 
                   การประเมินคุณธรรมและความโปร่งใสในการดำเนินงานของหน่วยงานภาครัฐ (Integrity and Transparency Assessment : ITA) เป็นเครื่องมือการประเมินเชิงบวกเพื่อเป็นมาตรการป้องกันการทุจริต และ เป็นกลไกในการสร้างความตระหนักให้หน่วยงานภาครัฐมีการดำเนินงานอย่างโปร่งใสและมีคุณธรรม ซึ่ง ประกอบด้วย 10 ตัวชี้วัด ดังนี้
                   ตัวชี้วัดที่ 1 การปฏิบัติหน้าที่ 
                   ตัวชี้วัดที่ 2 การใช้งบประมาณ 
                   ตัวชี้วัดที่ 3 การใช้อำนาจ 
                   ตัวชี้วัดที่ 4 การใช้ทรัพย์สินของทางราชการ 
