                        การวางแผนด้านอัตรากำลัง หมายถึง กระบวนการวิเคราะห์อัตรากำลังของบุคลากรทั้งสายวิชาการและสายสนับสนุนที่ต้องการอย่างเพียงพอที่จะดำเนินการตามกระบวนการทำงานตามพันธกิจสำคัญที่สถาบันกำหนดให้สำเร็จ รวมทั้งคำนึงถึงการตอบสนองความต้องการกำลังคนตามความต้องการที่มีการเปลี่ยนแปลงในสถานการณ์ปกติและสถานการณ์ที่ไม่คาดหมาย
                        การสรรหาบุคลากร หมายถึง กระบวนการจัดการเพื่อให้สถาบันมีบุคลากรใหม่ทั้งสายวิชาการและสายสนับสนุนที่มีคุณสมบัติและสมรรถนะเพียงพอในการตอบสนองความสำเร็จของสถาบันในการดำเนินการพันธกิจที่สำคัญ ครอบคลุมถึงกระบวนการกำหนดคุณสมบัติที่สอดคล้องกับแผนกลยุทธ์/ยุทธศาสตร์ กระบวนการคัดเลือกบุคลากร กระบวนการว่าจ้างและบรรจุ รวมถึงระบบการดูแลบุคลากรใหม่
                        การเปลี่ยนแปลงในสถานการณ์ปกติและสถานการณ์ที่ไม่คาดหมาย หมายถึง เหตุการณ์การเปลี่ยนแปลงต่างๆที่สถาบันควรนำมาพิจารณาทั้งในเรื่องขีดความสามารถและอัตรากำลังให้มีความเพียงพอต่อการตอบสนองพันธกิจและสามารถดำเนินการได้อย่างต่อเนื่อง เช่น การเกษียณอายุราชการ การลาออก การเจ็บป่วย การเสียชีวิตของบุคลากร การเปิดหลักสูตรและบริการใหม่ ๆ การเปลี่ยนแปลงด้านโครงสร้าง ระบบงานที่ออกแบบใหม่ การใช้เทคโนโลยีทดแทนคน การจัดการภาวะหมดไฟของบุคลากร การเปลี่ยนแปลงด้านความต้องการของนักศึกษา และผู้รับบริการอื่น การพลิกโฉมองค์กร เป็นต้น',
