                      ปัจจัยขับเคลื่อนความผูกพัน หมายถึง สิ่งที่ทำให้บุคลากรเกิดแรงจูงใจในการปฏิบัติงานอย่างเต็มที่ให้แก่องค์กรและพร้อมที่จะเสียสละ ทุ่มเท สนับสนุนเพื่อให้องค์กรประสบความสำเร็จ สามารถค้นหาจากการสำรวจ การทำวิจัย การสนทนากลุ่ม เป็นต้น
