                      การประเมินผล หมายถึง กระบวนการวัดและประเมินผลลัพธ์การเรียนรู้ระดับหลักสูตร ระดับชั้นปี และระดับรายวิชา โดยใช้วิธีการ เครื่องมือ และเกณฑ์การตัดสินผลที่เหมาะสม มีความตรง ความเที่ยง และยุติธรรม และมีการทบทวน ตรวจสอบ กำกับ การให้ข้อมูลป้อนกลับ นำไปสู่การปรับปรุง/พัฒนาคุณภาพการเรียนการสอนของผู้สอนและผู้เรียน เพื่อให้มั่นใจว่าผู้เรียนบรรลุผลลัพธ์การเรียนรู้ที่คาดหวัง
