                'description' => 'ตำรา หมายถึง ผลงานวิชาการที่ใช้สำหรับการเรียนการสอนทั้งวิชา หรือเป็นส่วนหนึ่งของวิชา ซึ่งเกิดจากการนำข้อค้นพบจากทฤษฎีจากงานวิจัยของตนเอง หรือความรู้ที่ได้จากการค้นคว้าศึกษา มาวิเคราะห์ สังเคราะห์รวบรวมและเรียบเรียง โดยมีมโนทัศน์ที่ผู้เขียนกำหนดให้เป็นแกนกลาง ซึ่งสัมพันธ์กับมโนทัศน์ย่อยอื่นอย่างเป็นระบบ มีเอกภาพ สัมพันธภาพ และสารัตถภาพตามหลักการเขียนที่ดี ใช้ภาษาที่เป็นมาตรฐานทางวิชาการ และให้ความรู้ใหม่ อันเป็นความรู้สำคัญที่มีผลให้เกิดความเปลี่ยนแปลงต่อวงการวิชาการนั้น ๆ เนื้อหาสาระของตำราต้องมีความทันสมัย เป็นรูปเล่มที่ประกอบด้วย คำนำ สารบัญ เนื้อเรื่อง การอธิบายหรือการวิเคราะห์ การสรุป การอ้างอิง บรรณานุกรม และดัชนีค้นคำ ทั้งนี้ควรมีการอ้างอิงแหล่งข้อมูลที่ทันสมัยและ ครบถ้วนสมบูรณ์ การอธิบายสาระสำคัญมีความชัดเจน โดยอาจใช้ข้อมูล แผนภาพ ตัวอย่าง หรือกรณีศึกษาประกอบจนผู้อ่านสามารถทำความเข้าใจในสาระสำคัญนั้นได้โดยเบ็ดเสร็จ
                      หนังสือ หมายถึง ผลงานวิชาการที่เกิดจากการค้นคว้าศึกษาความรู้ในเรื่องใดเรื่องหนึ่งอย่างรอบด้านและลึกซึ้ง มีการวิเคราะห์ สังเคราะห์และเรียบเรียงอย่างเป็นระบบ ประกอบด้วยมโนทัศน์หลัก ที่เป็นแกนกลางและมโนทัศน์ย่อยที่สัมพันธ์กัน มีความละเอียดลึกซึ้ง ใช้ภาษาที่เป็นมาตรฐานทางวิชาการ ให้ทัศนะของผู้เขียนที่สร้างเสริมปัญญาความคิดและสร้างความแข็งแกร่งทางวิชาการให้แก่สาขาวิชานั้น ๆ หรือสาขาวิชาที่เกี่ยวข้อง เนื้อหาของหนังสือไม่จำเป็นต้องสอดคล้องหรือเป็นไปตามข้อกำหนดของหลักสูตรหรือของวิชาใดวิชาหนึ่ง ในหลักสูตรและ ไม่จำเป็นต้องนำไปใช้ประกอบการเรียนการสอนในวิชาใดวิชาหนึ่ง เนื้อหาสาระของหนังสือต้องมีความทันสมัย เป็นรูปเล่มที่ประกอบด้วย คำนำ สารบัญ เนื้อเรื่อง การวิเคราะห์ การสรุป การอ้างอิง บรรณานุกรม และดัชนีค้นคำ ที่ทันสมัยและครบถ้วนสมบูรณ์ โดยอาจมีข้อมูล แผนภาพ ตัวอย่าง หรือกรณีศึกษาประกอบด้วยก็ได้ ตามรูปแบบอย่างใดอย่างหนึ่งต่อไปนี้ ๑. เป็นงานที่นักวิชาการเขียนทั้งเล่ม (authored book) คือเอกสารที่ผู้เขียนเรียบเรียง ขึ้นทั้งเล่มอย่างมีเอกภาพ มีรากฐานทางวิชาการที่มั่นคง และให้ทัศนะของผู้เขียนที่สร้าง เสริมปัญญา ความคิด และสร้างความแข็งแกร่งทางวิชาการ ๒. เป็นงานวิชาการบางบทหรือส่วนหนึ่งในหนังสือที่มีผู้เขียนหลายคน (book chapter) โดยจะต้องมีความเป็นเอกภาพของเนื้อหาวิชาการ ซึ่งผู้อ่านสามารถทำความเข้าใจ ในสาระสำคัญนั้นได้โดยเบ็ดเสร็จในแต่ละบท และเป็นงานศึกษาค้นคว้าอย่างมีระบบ มีการวิเคราะห์และสังเคราะห์ข้อมูลด้วยวิธีวิทยาอันเป็นที่ยอมรับจนได้ข้อสรุปที่ทำให้เกิด ความก้าวหน้าทางวิชาการ หรือนำไปประยุกต์ใช้ได้ กรณีที่ในแต่ละบทมีผู้เขียนหลายคน จะต้องระบุบทบาทหน้าที่ของแต่ละคนอย่างชัดเจน จำนวนบทที่จะนำมาแทนหนังสือ ๑ เล่ม ต้องมีจำนวนอย่างน้อย ๕ บท และมีจำนวนหน้ารวมกันแล้วไม่น้อยกว่า ๘๐ หน้า โดยเนื้อหาสาระของบทในหนังสือทั้ง ๕ บท จะต้องไม่ซ้ำซ้อนกัน
